prometheus.query:
(
  histogram_quantile(0.95,
    sum by (le) (rate(sa_http_request_duration_slo_seconds_bucket{job="{{args.service-name}}",route="{{args.route}}",method="{{args.method}}",rollout_hash="{{args.canary-hash}}",status_class=~"2xx|3xx"}[2m]))
  )
  and on() (sum(increase(sa_http_request_duration_slo_seconds_bucket{job="{{args.service-name}}",route="{{args.route}}",method="{{args.method}}",rollout_hash="{{args.canary-hash}}",status_class=~"2xx|3xx",le="+Inf"}[2m])) >= 10)
) or on() vector(-1)

